fn checked_validator_storage_bytes(stream: &XmlTokenStream, collected_capacity: usize) -> Option<usize> {
    collected_capacity.checked_mul(size_of::<XmlToken>())?
        .checked_add(stream.token_storage_bytes())?
        .checked_add(stream.open_name_storage_bytes())?
        .checked_add(stream.visitor_storage_bytes())
}

fn checked_total_storage_bytes(metadata_bytes: usize, validator_bytes: usize) -> Option<usize> {
    if metadata_bytes > MAX_COMPONENT_BYTES || validator_bytes > MAX_COMPONENT_BYTES { return None; }
    let total = metadata_bytes.checked_add(validator_bytes)?;
    (total <= MAX_STORAGE_BYTES).then_some(total)
}

fn source_exceeds_limit(source_bytes: usize) -> bool {
    source_bytes > MAX_SOURCE_BYTES || source_bytes > MAX_LARGE_INPUT_BYTES
}

fn reserve_tokens(tokens: &mut Vec<XmlToken>, requested_capacity: usize,
    xml_storage_bytes: usize) -> Result<usize, ElementReserveError> {
    reserve_tokens_with_budget(tokens, requested_capacity, xml_storage_bytes, MAX_COMPONENT_BYTES)
}

fn next_token_capacity(current_capacity: usize, xml_storage_bytes: usize,
    component_budget: usize) -> Result<usize, ElementReserveError> {
    let legal_capacity = component_budget.checked_sub(xml_storage_bytes)
        .ok_or(ElementReserveError::Limit)? / size_of::<XmlToken>();
    if current_capacity >= legal_capacity { return Err(ElementReserveError::Limit); }
    let preferred = if current_capacity == 0 { 64 } else {
        current_capacity.checked_mul(2).unwrap_or(legal_capacity)
    };
    Ok(preferred.min(legal_capacity))
}

fn reserve_tokens_with_budget(tokens: &mut Vec<XmlToken>, requested_capacity: usize,
    xml_storage_bytes: usize, component_budget: usize) -> Result<usize, ElementReserveError> {
    let legal_capacity = component_budget.checked_sub(xml_storage_bytes)
        .ok_or(ElementReserveError::Limit)? / size_of::<XmlToken>();
    let requested_capacity = requested_capacity.min(legal_capacity);
    if requested_capacity < tokens.len() { return Err(ElementReserveError::Limit); }
    let mut candidate = Vec::new();
    candidate.try_reserve_exact(requested_capacity).map_err(|_| ElementReserveError::OutOfMemory)?;
    install_token_candidate(tokens, candidate, xml_storage_bytes, component_budget)
}

fn install_token_candidate(tokens: &mut Vec<XmlToken>, mut candidate: Vec<XmlToken>,
    xml_storage_bytes: usize, component_budget: usize) -> Result<usize, ElementReserveError> {
    let candidate_bytes = candidate.capacity().checked_mul(size_of::<XmlToken>())
        .ok_or(ElementReserveError::Limit)?;
    let total = candidate_bytes.checked_add(xml_storage_bytes).ok_or(ElementReserveError::Limit)?;
    if candidate.capacity() < tokens.len() || total > component_budget {
        return Err(ElementReserveError::Limit);
    assert_eq!(session.progress().bytes_read, 0);
    assert!(session.progress().first_preview_ready);
    assert_eq!(session.progress().diagnostic, XmlDiagnostic {
        category: XmlError::MismatchedTag, offset: error_offset,
    });
    assert_eq!(session.make_preview_source().unwrap(),
        b"<svg width='2' height='2'><rect width='1' height='1'/></svg>");
}

#[test]
fn oversized_owned_element_candidate_is_rejected_without_replacing_partial_index() {
    let original = IndexElement {
        parent: usize::MAX,
        source_offset: 11,
        source_length: 17,
        name_offset: 12,
        name_length: 3,
        depth: 0,
        support: ElementSupport::Unsupported,
        closed: false,
    };
    let mut elements = vec![original];
    let original_capacity = elements.capacity();

    let mut detached = Vec::new();
    detached.try_reserve_exact(1).unwrap();
    assert!(detached.capacity() >= 1);
    let result = install_element_candidate(&mut elements, detached, 0);

    assert_eq!(result, Err(ElementReserveError::Limit));
    assert_eq!(elements.as_slice(), &[original]);
    assert_eq!(elements.capacity(), original_capacity);
}

#[test]
fn exact_validator_capacity_and_combined_storage_budgets_are_charged() {
    let stream = XmlTokenStream::new_visitor(b"<svg><rect/></svg>").unwrap();
    let xml_storage = stream.token_storage_bytes()
        .checked_add(stream.open_name_storage_bytes()).unwrap()
        .checked_add(stream.visitor_storage_bytes()).unwrap();
    assert_eq!(checked_validator_storage_bytes(&stream, 0), Some(xml_storage));
    assert!(xml_storage <= MAX_COMPONENT_BYTES);
    assert_eq!(checked_total_storage_bytes(MAX_COMPONENT_BYTES, MAX_COMPONENT_BYTES), Some(MAX_STORAGE_BYTES));
    assert_eq!(checked_total_storage_bytes(MAX_COMPONENT_BYTES + 1, 0), None);
    assert_eq!(checked_total_storage_bytes(usize::MAX, 1), None);

    let mut tokens = Vec::new();
    let exact_candidate_capacity = 64;
    let charged = reserve_tokens(&mut tokens, exact_candidate_capacity, xml_storage).unwrap();
    assert_eq!(charged, tokens.capacity() * size_of::<XmlToken>() + xml_storage);
    assert!(charged <= MAX_COMPONENT_BYTES);
}

#[test]
fn exact_metadata_capacity_and_source_limit_boundaries_are_preserved() {
    let mut candidate = Vec::new();
    candidate.try_reserve_exact(1).unwrap();
    let exact_capacity_bytes = candidate.capacity().checked_mul(size_of::<IndexElement>()).unwrap();
    let mut elements = Vec::new();
    assert_eq!(install_element_candidate(&mut elements, candidate, exact_capacity_bytes), Ok(exact_capacity_bytes));
    assert_eq!(elements.capacity().checked_mul(size_of::<IndexElement>()), Some(exact_capacity_bytes));
    let metadata_bytes = size_of::<[OpenElement; MAX_DEPTH]>() + exact_capacity_bytes;
    assert_eq!(checked_total_storage_bytes(metadata_bytes, MAX_COMPONENT_BYTES), Some(metadata_bytes + MAX_COMPONENT_BYTES));
    assert_eq!(source_exceeds_limit(MAX_SOURCE_BYTES.min(MAX_LARGE_INPUT_BYTES)), false);
    assert_eq!(source_exceeds_limit(MAX_SOURCE_BYTES.min(MAX_LARGE_INPUT_BYTES) + 1), true);
}

#[test]
fn collector_growth_clamps_to_last_legal_token_and_drops_oversized_candidates() {
    let token_bytes = size_of::<XmlToken>();
    let xml_storage = 17;
    let token = vexel_xml::tokenize(b"<svg/>", vexel_xml::XmlLimits::default()).0[0];
    for legal_capacity in [1, 3, 5, 65] {
        for remainder in [0, 1, token_bytes - 1] {
            let budget = xml_storage + legal_capacity * token_bytes + remainder;
            let mut tokens = Vec::new();
            let mut previous_capacity = 0;
            while tokens.len() < legal_capacity {
                if tokens.len() == tokens.capacity() {
                    let next = next_token_capacity(tokens.capacity(), xml_storage, budget).unwrap();
                    assert!(next > tokens.capacity());
                    assert!(next <= legal_capacity);
                    let prior_tokens = tokens.clone();
                    let charged = reserve_tokens_with_budget(&mut tokens, next, xml_storage, budget).unwrap();
                    assert_eq!(tokens, prior_tokens);
                    assert_eq!(charged, xml_storage + tokens.capacity() * token_bytes);
                    assert!(charged <= budget);
                    assert!(tokens.capacity() > previous_capacity);
                    previous_capacity = tokens.capacity();
                }
                tokens.push(token);
            }
            assert_eq!(tokens.capacity(), legal_capacity);
            assert_eq!(next_token_capacity(tokens.capacity(), xml_storage, budget), Err(ElementReserveError::Limit));

            let original_pointer = tokens.as_ptr();
            let original_capacity = tokens.capacity();
            let mut oversized = Vec::new();
            oversized.try_reserve_exact(legal_capacity + 1).unwrap();
            assert_eq!(install_token_candidate(&mut tokens, oversized, xml_storage, budget), Err(ElementReserveError::Limit));
            assert_eq!(tokens.as_ptr(), original_pointer);
            assert_eq!(tokens.capacity(), original_capacity);
            assert_eq!(tokens.as_slice(), vec![token; legal_capacity]);
        }
    }
    assert_eq!(next_token_capacity(4, xml_storage, xml_storage + 5 * token_bytes), Ok(5));
    assert_eq!(next_token_capacity(0, xml_storage, xml_storage + token_bytes - 1), Err(ElementReserveError::Limit));
    assert_eq!(next_token_capacity(0, xml_storage, xml_storage - 1), Err(ElementReserveError::Limit));
    assert_eq!(next_token_capacity(usize::MAX, 0, usize::MAX), Err(ElementReserveError::Limit));
}
